    nonisolated struct Idle: Sendable {}
    nonisolated struct Running: Sendable {}
    nonisolated struct Left: Sendable {}
    nonisolated struct Right: Sendable {}
    @Initial case idle(Idle)
    case running(Running)
    @Terminal case left(Left)
    @Terminal case right(Right)
    enum Input: Sendable { case go, pick(Int) }
    @Operation(activeIn: [Running.self])
    enum Load { typealias Output = Seed }
    @Transition(on: Input.go, starts: [Load.self])
    fileprivate static func go(_ source: Idle) -> Change<Running, Effect.Go> { Change(Running(), effects: [.load]) }
    @Transition(onSuccess: Load.self)
    fileprivate static func loaded(_ source: Running, _ value: Load.Output) -> Idle { Idle() }
    @Transition(on: Input.pick)
    fileprivate static func goLeft(_ source: Idle, _ value: Int) throws(Problem<A1024>) -> Left { Left() }
    @Transition(on: Input.pick)
    fileprivate static func goRight(_ source: Idle, _ value: Int) throws(Problem<A1023.Next>) -> Right { Right() }
    @Route(on: Input.pick)
    fileprivate static func pick(_ source: Idle, _ value: Int) -> Route.Pick { value < 10 ? .goLeft : .goRight }
}

func picked(_ idle: Flow.Observed<Flow.Idle>) -> Flow.Problem<Flow.A1024>? {
    do {
        _ = try idle.pick(1)
        return nil
    } catch {
        return error
    }
